use serde::Deserialize;
#[derive(Debug,Deserialize,Clone,PartialEq)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Inference {pub version:u32,pub id:String,pub model:Model,pub inputs:Vec<Tensor>,pub outputs:Vec<Tensor>,pub execution:Policy,pub file:String}
#[derive(Debug,Deserialize,Clone,PartialEq)]#[serde(deny_unknown_fields)]pub struct Model{pub resource:String,pub sha256:String,pub bytes:u64}
#[derive(Debug,Deserialize,Clone,PartialEq)]#[serde(deny_unknown_fields)]pub struct Tensor{pub name:String,pub dtype:String,pub shape:Vec<i64>,pub layout:String,pub semantic:Option<String>}
#[derive(Debug,Deserialize,Clone,PartialEq)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct Policy{pub provider:String,pub allow_cpu_fallback:bool,pub precision:String,pub temporal:String}
impl Tensor{pub fn bytes(&self)->Result<u64,String>{if self.name.is_empty()||self.name.contains('\0')||self.dtype!="float32"||!matches!(self.layout.as_str(),"NCHW"|"NHWC"|"NC"|"linear"){return Err("E_INFERENCE_DTYPE: resident v1 needs a named F32 tensor with explicit layout".into());}self.shape.iter().try_fold(4u64,|n,&d|if d>0{n.checked_mul(d as u64).ok_or("E_INFERENCE_SHAPE: tensor byte overflow".into())}else{Err("E_INFERENCE_SHAPE: positive static dimensions required".into())})}}
impl Inference{
 pub fn validate(&self)->Result<u64,String>{if self.version!=1||self.id.is_empty()||self.id.contains('\0')||self.model.resource.is_empty()||self.model.resource.contains('\0')||self.model.bytes==0||self.model.sha256.len()!=64||!self.model.sha256.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))||self.inputs.is_empty()||self.outputs.is_empty()||!matches!(self.execution.provider.as_str(),"directml"|"cuda"|"tensorrt"|"coreml"|"openvino"|"migraphx"|"cpu"|"auto")||self.execution.precision!="float32"||self.execution.temporal!="stateless"||self.file.len()!=53||!self.file.ends_with(".onnx")||!self.file.is_ascii()||!self.file.as_bytes()[..48].iter().copied().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)){return Err("E_INFERENCE_SCHEMA: invalid sealed embedded-model v1 profile".into());}
  let mut bytes=0u64;for group in [&self.inputs,&self.outputs]{let mut names=std::collections::HashSet::new();for t in group{if !names.insert(&t.name){return Err("E_INFERENCE_SCHEMA: duplicate tensor name".into());}bytes=bytes.checked_add(t.bytes()?.checked_add(65535).and_then(|v|v.checked_div(65536)).and_then(|v|v.checked_mul(65536)).ok_or("E_INFERENCE_BUDGET: allocation overflow")?).ok_or("E_INFERENCE_BUDGET: byte overflow")?;}}Ok(bytes)
 }
}
